import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { ImageIds } from '../types'
import { cells, decodePng, fit, fromBase64 } from './png'
import type { Decoded } from './png'

const ids = atom({ plugin: 'paste-image-preview', key: 'ids' } as const, [] as ImageIds)

const PLACEHOLDER = /\[Image #(\d+)\]/g
const MAX_SHOWN = 4
const MAX_COLUMNS = 48
const MAX_ROWS = 12
const GAP = 2
// What one read of `$.fs.read` may copy in.
const MAX_BYTES = 4 * 1024 * 1024
// The size a picture is decoded down to once, before each layout's resize.
const DECODE_WIDTH = MAX_COLUMNS * 2
const DECODE_HEIGHT = MAX_ROWS * 4

// The image's file, when there is one to open, and its picture or why not.
type Found = { file?: string } & ({ decoded: Decoded } | { reason: string })

// The draft's last image list, so a keystroke that keeps it writes nothing.
let lastSeen: string | undefined
// Decoded pictures by path, size and mtime, so a redraw decodes nothing.
const decodedByFile = new Map<string, Found>()
let dirOfSession: { session: string; dir: string } | undefined

async function sync($: EngineInterface, text: string): Promise<void> {
  const found = [...new Set([...text.matchAll(PLACEHOLDER)].map(m => Number(m[1])))]
  const seen = found.join(',')
  if (seen === lastSeen) return
  lastSeen = seen
  await update($, ids, () => found)
}

// Where the engine keeps this session's pasted images:
// <temp>/claude/<project, every non-alphanumeric as '-'>/<session id>/images
async function imagesDir($: EngineInterface): Promise<string | undefined> {
  const session = await $.session.id()
  if (dirOfSession?.session === session) return dirOfSession.dir
  const temps = [
    await $.env.get('CLAUDE_CODE_TMPDIR'),
    await $.env.get('TEMP'),
    await $.env.get('TMP'),
    await $.env.get('TMPDIR'),
  ]
  const roots = [...new Set(temps.filter((t): t is string => !!t))]
  const projects = [...new Set([await $.session.root(), await $.session.cwd()])].map(p =>
    p.replace(/[^a-zA-Z0-9]/g, '-'),
  )
  for (const root of roots) {
    const sep = root.includes('\\') ? '\\' : '/'
    const base = `${root.replace(/[\\/]+$/, '')}${sep}claude`
    if (!(await $.fs.exists(base))) continue
    const candidates = projects.map(project => [base, project, session, 'images'].join(sep))
    // A project path the engine names otherwise (a long one, shortened).
    for (const entry of await $.fs.list(base)) {
      if (entry.kind === 'dir') candidates.push([base, entry.name, session, 'images'].join(sep))
    }
    for (const dir of candidates) {
      if (await $.fs.exists(dir)) {
        dirOfSession = { session, dir }
        return dir
      }
    }
  }
  return undefined
}

async function load($: EngineInterface, dir: string, id: number): Promise<Found> {
  const entry = (await $.fs.list(dir)).find(f => f.kind === 'file' && f.name.startsWith(`${id}.`))
  if (!entry) return { reason: '缓存目录里没有这张图' }
  const file = `${dir}${dir.includes('\\') ? '\\' : '/'}${entry.name}`
  if (!entry.name.toLowerCase().endsWith('.png')) return { file, reason: `${entry.name} 不是 PNG，暂不支持预览` }
  if (entry.size > MAX_BYTES) {
    return { file, reason: `图片 ${(entry.size / 1048576).toFixed(1)}MB，超过插件可读的 4MB，未预览` }
  }
  const cacheKey = `${file}|${entry.size}|${entry.mtimeMs}`
  const cached = decodedByFile.get(cacheKey)
  if (cached) return cached
  let found: Found
  try {
    const { base64 } = await $.fs.read(file, { as: 'bytes' })
    found = { file, decoded: decodePng(fromBase64(base64), DECODE_WIDTH, DECODE_HEIGHT) }
  } catch (error) {
    found = { file, reason: `解码失败：${error instanceof Error ? error.message : String(error)}` }
  }
  decodedByFile.set(cacheKey, found)
  return found
}

// Opens the original in the system's own viewer.
async function openFile($: EngineInterface, file: string): Promise<void> {
  try {
    if (file.includes('\\')) {
      // explorer.exe answers 1 even when it opened the file.
      const { exitCode, stderr } = await $.process.run(['explorer.exe', file])
      if (exitCode > 1) $.ui.toast(`打开原图失败（${exitCode}）：${stderr.trim() || file}`)
      return
    }
    const { exitCode, stderr } = await $.process.run(['open', file]).catch(() => $.process.run(['xdg-open', file]))
    if (exitCode !== 0) $.ui.toast(`打开原图失败（${exitCode}）：${stderr.trim() || file}`)
  } catch (error) {
    $.ui.toast(`打开原图失败：${error instanceof Error ? error.message : String(error)}`)
  }
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    lastSeen = undefined
    await sync($, (await $.prompt.read()).text)
    return started
  })

  on('prompt.edit', async ($, e, next) => {
    const box = await next(e)
    await sync($, box.text)
    return box
  })

  on('prompt.change', async ($, e, next) => {
    await sync($, e.text)
    return next(e)
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.surface !== 'terminal' || e.props.hasSurvey) return next(e)
    const shown = await read($, ids)
    if (shown.length === 0) return next(e)

    const { Box, Button, Text, Raster } = $.ui.resolve(e)
    const dir = await imagesDir($)
    const list = shown.slice(0, MAX_SHOWN)
    const across = Math.floor((e.props.bodyColumns - GAP * (list.length - 1)) / list.length)
    const isRow = across >= 12
    const maxColumns = Math.max(4, Math.min(MAX_COLUMNS, isRow ? across : e.props.bodyColumns))
    // The heading and the button take a row each.
    const maxRows = Math.max(2, Math.min(MAX_ROWS, e.props.maxRows - 3))

    const items = []
    for (const [index, id] of list.entries()) {
      const found: Found = dir ? await load($, dir, id) : { reason: '找不到本会话的图片缓存目录' }
      const { file } = found
      const box = 'decoded' in found ? fit(found.decoded.width, found.decoded.height, maxColumns, maxRows) : undefined
      items.push(
        <Box key={`item-${id}`} flexDirection="column" width={isRow ? maxColumns : undefined}>
          <Text dimColor wrap="truncate">
            [Image #{id}] {'decoded' in found ? `${found.decoded.width}×${found.decoded.height}` : found.reason}
          </Text>
          {file ? (
            <Button
              key={`open-${id}`}
              label="打开原图"
              hotkey={String(index + 1)}
              dimColor
              onPress={() => openFile($, file)}
            />
          ) : null}
          {'decoded' in found && box ? (
            <Raster
              key={`image-${id}`}
              columns={box.columns}
              rows={box.rows}
              cells={cells(found.decoded.small, box.columns, box.rows)}
            />
          ) : null}
        </Box>,
      )
    }

    return (
      <Box flexDirection="column">
        <Box flexDirection={isRow ? 'row' : 'column'} columnGap={GAP}>
          {items}
        </Box>
        {shown.length > MAX_SHOWN ? <Text dimColor>还有 {shown.length - MAX_SHOWN} 张未显示</Text> : null}
      </Box>
    )
  })
}

